using System;using System.IO;using System.Linq;
class Program{static string Hex(string s)=>string.Concat(s.Select(c=>((int)c).ToString("x4")));static void Main(string[]args){foreach(int size in new[]{0,1,2,3,4,7,4096,4097,65536}){try{var f=new FileStream(args[0],FileMode.Open,FileAccess.Read,FileShare.Read,1);Console.Write("L"+(f.CanSeek?f.Length:-1)+":");byte[]b=new byte[size];for(int i=0;i<4;i++){int n=f.Read(b,0,b.Length);ulong sum=0;for(int j=0;j<n;j++)sum=unchecked(sum*131+b[j]);Console.Write($"{n},{sum};");}f.Close();Console.Write("CL"+(f.CanSeek?f.Length:-1)+":");try{f.Read(b,0,b.Length);}catch(Exception e){Console.Write($"{e.GetType().FullName}:{unchecked((uint)e.HResult)}:{Hex(e.Message)}");}Console.WriteLine();}catch(Exception e){Console.WriteLine($"E:{e.GetType().FullName}:{unchecked((uint)e.HResult)}:{Hex(e.Message)}:{(e is FileNotFoundException x?Hex(x.FileName):"-")}");}}}}
